insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values
('CF/88 — art. 37 (caput)', 'A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte:', '1988-10-05', 14, 64),
('CF/88 — art. 37, I', 'os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei;', '1988-10-05', 14, 64),
('CF/88 — art. 37, II', 'a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração;', '1988-10-05', 14, 64),
('CF/88 — art. 37, III', 'o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;', '1988-10-05', 14, 64),
('CF/88 — art. 37, IV', 'durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;', '1988-10-05', 14, 64),
('CF/88 — art. 37, V', 'as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento;', '1988-10-05', 14, 64),
('CF/88 — art. 37, VI', 'é garantido ao servidor público civil o direito à livre associação sindical;', '1988-10-05', 14, 64),
('CF/88 — art. 37, VII', 'o direito de greve será exercido nos termos e nos limites definidos em lei específica;', '1988-10-05', 14, 64),
('CF/88 — art. 37, VIII', 'a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;', '1988-10-05', 14, 64),
('CF/88 — art. 37, IX', 'a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;', '1988-10-05', 14, 64),
('CF/88 — art. 37, X', 'a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XI', 'a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XII', 'os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XIII', 'é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XIV', 'os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XV', 'o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XVI', 'é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: a) a de dois cargos de professor; b) a de um cargo de professor com outro de qualquer natureza; c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XVII', 'a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XVIII', 'a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XIX', 'somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XX', 'depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;', '1988-10-05', 14, 64),
('CF/88 — art. 37, XXI', 'ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.', '1988-10-05', 14, 64),
('CF/88 — art. 37, XXII', 'as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 1º', 'A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 2º', 'A não observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 3º', 'A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 3º, inciso I', 'as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 3º, inciso II', 'o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 3º, inciso III', 'a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 4º', 'Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 5º', 'A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 6º', 'As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 7º', 'A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 8º', 'A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre: (Vigência)', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 8º, inciso I', 'o prazo de duração do contrato;', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 8º, inciso II', 'os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 8º, inciso III', 'a remuneração do pessoal.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 9º', 'O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 10', 'É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 11', 'Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 12', 'Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 13', 'O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 14', 'A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 15', 'É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social.', '1988-10-05', 14, 64),
('CF/88 — art. 37, § 16', 'Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei.', '1988-10-05', 14, 64),
('CF/88 — art. 5º (caput)', 'Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:', '1988-10-05', 15, 76),
('CF/88 — art. 5º, I', 'homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, II', 'ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, III', 'ninguém será submetido a tortura nem a tratamento desumano ou degradante;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, IV', 'é livre a manifestação do pensamento, sendo vedado o anonimato;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, V', 'é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, VI', 'é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, VII', 'é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, VIII', 'ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, IX', 'é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, X', 'são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XI', 'a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial; (Vigência)', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XII', 'é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XIII', 'é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XIV', 'é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XV', 'é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XVI', 'todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XVII', 'é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XVIII', 'a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XIX', 'as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XX', 'ninguém poderá ser compelido a associar-se ou a permanecer associado;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXI', 'as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXII', 'é garantido o direito de propriedade;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXIII', 'a propriedade atenderá a sua função social;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXIV', 'a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXV', 'no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXVI', 'a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXVII', 'aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXVIII', 'são assegurados, nos termos da lei: a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas; b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXIX', 'a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXX', 'é garantido o direito de herança;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXI', 'a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do "de cujus";', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXII', 'o Estado promoverá, na forma da lei, a defesa do consumidor;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXIII', 'todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXIV', 'são a todos assegurados, independentemente do pagamento de taxas: a) o direito de petição aos Poderes Públicos em defesa de direitos ou contra ilegalidade ou abuso de poder; b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXV', 'a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXVI', 'a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXVII', 'não haverá juízo ou tribunal de exceção;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXVIII', 'é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados: a) a plenitude de defesa; b) o sigilo das votações; c) a soberania dos veredictos; d) a competência para o julgamento dos crimes dolosos contra a vida;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XXXIX', 'não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XL', 'a lei penal não retroagirá, salvo para beneficiar o réu;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLI', 'a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLII', 'a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLIII', 'a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura , o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLIV', 'constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLV', 'nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLVI', 'a lei regulará a individualização da pena e adotará, entre outras, as seguintes: a) privação ou restrição da liberdade; b) perda de bens; c) multa; d) prestação social alternativa; e) suspensão ou interdição de direitos;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLVII', 'não haverá penas: a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX; b) de caráter perpétuo; c) de trabalhos forçados; d) de banimento; e) cruéis;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLVIII', 'a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, XLIX', 'é assegurado aos presos o respeito à integridade física e moral;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, L', 'às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LI', 'nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LII', 'não será concedida extradição de estrangeiro por crime político ou de opinião;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LIII', 'ninguém será processado nem sentenciado senão pela autoridade competente;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LIV', 'ninguém será privado da liberdade ou de seus bens sem o devido processo legal;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LV', 'aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e ampla defesa, com os meios e recursos a ela inerentes;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LVI', 'são inadmissíveis, no processo, as provas obtidas por meios ilícitos;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LVII', 'ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LVIII', 'o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LIX', 'será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LX', 'a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXI', 'ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXII', 'a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXIII', 'o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXIV', 'o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXV', 'a prisão ilegal será imediatamente relaxada pela autoridade judiciária;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXVI', 'ninguém será levado à prisão ou nela mantido, quando a lei admitir a liberdade provisória, com ou sem fiança;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXVII', 'não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXVIII', 'conceder-se-á "habeas-corpus" sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXIX', 'conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por "habeas-corpus" ou "habeas-data", quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do Poder Público;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXX', 'o mandado de segurança coletivo pode ser impetrado por: a) partido político com representação no Congresso Nacional; b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXI', 'conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXII', 'conceder-se-á "habeas-data": a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público; b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXIII', 'qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXIV', 'o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXV', 'o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXVI', 'são gratuitos para os reconhecidamente pobres, na forma da lei: a) o registro civil de nascimento; b) a certidão de óbito;', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXVII', 'são gratuitas as ações de "habeas-corpus" e "habeas-data", e, na forma da lei, os atos necessários ao exercício da cidadania.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXVIII', 'a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, LXXIX', 'é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, § 1º', 'As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, § 2º', 'Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, § 3º', 'Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais.', '1988-10-05', 15, 76),
('CF/88 — art. 5º, § 4º', 'O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. CAPÍTULO II DOS DIREITOS SOCIAIS', '1988-10-05', 15, 76),
('Lei nº 8.112/1990 — art. 116 (caput)', 'São deveres do servidor:', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, I', 'exercer com zelo e dedicação as atribuições do cargo;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, II', 'ser leal às instituições a que servir;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, III', 'observar as normas legais e regulamentares;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, IV', 'cumprir as ordens superiores, exceto quando manifestamente ilegais;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, V', 'atender com presteza: a) ao público em geral, prestando as informações requeridas, ressalvadas as protegidas por sigilo; b) à expedição de certidões requeridas para defesa de direito ou esclarecimento de situações de interesse pessoal; c) às requisições para a defesa da Fazenda Pública.', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, VI', 'levar as irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou, quando houver suspeita de envolvimento desta, ao conhecimento de outra autoridade competente para apuração;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, VII', 'zelar pela economia do material e a conservação do patrimônio público;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, VIII', 'guardar sigilo sobre assunto da repartição;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, IX', 'manter conduta compatível com a moralidade administrativa;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, X', 'ser assíduo e pontual ao serviço;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, XI', 'tratar com urbanidade as pessoas;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, XII', 'representar contra ilegalidade, omissão ou abuso de poder.', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 116, parágrafo único', 'A representação de que trata o inciso XII será encaminhada pela via hierárquica e apreciada pela autoridade superior àquela contra a qual é formulada, assegurando-se ao representando ampla defesa. Capítulo II Das Proibições', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117 (caput)', 'Ao servidor é proibido:', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, I', 'ausentar-se do serviço durante o expediente, sem prévia autorização do chefe imediato;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, II', 'retirar, sem prévia anuência da autoridade competente, qualquer documento ou objeto da repartição;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, III', 'recusar fé a documentos públicos;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, IV', 'opor resistência injustificada ao andamento de documento e processo ou execução de serviço;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, V', 'promover manifestação de apreço ou desapreço no recinto da repartição;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, VI', 'cometer a pessoa estranha à repartição, fora dos casos previstos em lei, o desempenho de atribuição que seja de sua responsabilidade ou de seu subordinado;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, VII', 'coagir ou aliciar subordinados no sentido de filiarem-se a associação profissional ou sindical, ou a partido político;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, VIII', 'manter sob sua chefia imediata, em cargo ou função de confiança, cônjuge, companheiro ou parente até o segundo grau civil;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, IX', 'valer-se do cargo para lograr proveito pessoal ou de outrem, em detrimento da dignidade da função pública;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, X', 'participar de gerência ou administração de sociedade privada, personificada ou não personificada, exercer o comércio, exceto na qualidade de acionista, cotista ou comanditário; (Redação dada pela Lei nº 11.784, de 2008', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XI', 'atuar, como procurador ou intermediário, junto a repartições públicas, salvo quando se tratar de benefícios previdenciários ou assistenciais de parentes até o segundo grau, e de cônjuge ou companheiro;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XII', 'receber propina, comissão, presente ou vantagem de qualquer espécie, em razão de suas atribuições;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XIII', 'aceitar comissão, emprego ou pensão de estado estrangeiro;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XIV', 'praticar usura sob qualquer de suas formas;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XV', 'proceder de forma desidiosa;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XVI', 'utilizar pessoal ou recursos materiais da repartição em serviços ou atividades particulares;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XVII', 'cometer a outro servidor atribuições estranhas ao cargo que ocupa, exceto em situações de emergência e transitórias;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XVIII', 'exercer quaisquer atividades que sejam incompatíveis com o exercício do cargo ou função e com o horário de trabalho;', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, XIX', 'recusar-se a atualizar seus dados cadastrais quando solicitado.', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, parágrafo único', 'A vedação de que trata o inciso X do caput deste artigo não se aplica nos seguintes casos: (Incluído pela Lei nº 11.784, de 2008', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, parágrafo único, inciso I', 'participação nos conselhos de administração e fiscal de empresas ou entidades em que a União detenha, direta ou indiretamente, participação no capital social ou em sociedade cooperativa constituída para prestar serviços a seus membros; e (Incluído pela Lei nº 11.784, de 2008', '1990-07-11', 14, 503),
('Lei nº 8.112/1990 — art. 117, parágrafo único, inciso II', 'gozo de licença para o trato de interesses particulares, na forma do art. 91 desta Lei, observada a legislação sobre conflito de interesses. (Incluído pela Lei nº 11.784, de 2008 Capítulo III Da Acumulação', '1990-07-11', 14, 503),
('Lei nº 9.784/1999 — art. 2 (caput)', 'A Administração Pública obedecerá, dentre outros, aos princípios da legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único', 'Nos processos administrativos serão observados, entre outros, os critérios de: I - atuação conforme a lei e o Direito; II - atendimento a fins de interesse geral, vedada a renúncia total ou parcial de poderes ou competências, salvo autorização em lei;', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único, inciso III', 'objetividade no atendimento do interesse público, vedada a promoção pessoal de agentes ou autoridades; IV - atuação segundo padrões éticos de probidade, decoro e boa-fé; V - divulgação oficial dos atos administrativos, ressalvadas as hipóteses de sigilo previstas na Constituição; VI - adequação entre meios e fins, vedada a imposição de obrigações, restrições e sanções em medida superior àquelas estritamente necessárias ao atendimento do interesse público;', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único, inciso VII', 'indicação dos pressupostos de fato e de direito que determinarem a decisão;', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único, inciso VIII', 'observância das formalidades essenciais à garantia dos direitos dos administrados; IX - adoção de formas simples, suficientes para propiciar adequado grau de certeza, segurança e respeito aos direitos dos administrados; X - garantia dos direitos à comunicação, à apresentação de alegações finais, à produção de provas e à interposição de recursos, nos processos de que possam resultar sanções e nas situações de litígio; XI - proibição de cobrança de despesas processuais, ressalvadas as previstas em lei;', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único, inciso XII', 'impulsão, de ofício, do processo administrativo, sem prejuízo da atuação dos interessados;', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 2, parágrafo único, inciso XIII', 'interpretação da norma administrativa da forma que melhor garanta o atendimento do fim público a que se dirige, vedada aplicação retroativa de nova interpretação. CAPÍTULO II DOS DIREITOS DOS ADMINISTRADOS', '1999-01-29', 14, 201),
('Lei nº 8.429/1992 — art. 9º (caput)', 'Constitui ato de improbidade administrativa importando em enriquecimento ilícito auferir, mediante a prática de ato doloso, qualquer tipo de vantagem patrimonial indevida em razão do exercício de cargo, de mandato, de função, de emprego ou de atividade nas entidades referidas no art. 1º desta Lei, e notadamente:', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, I', 'receber, para si ou para outrem, dinheiro, bem móvel ou imóvel, ou qualquer outra vantagem econômica, direta ou indireta, a título de comissão, percentagem, gratificação ou presente de quem tenha interesse, direto ou indireto, que possa ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, II', 'perceber vantagem econômica, direta ou indireta, para facilitar a aquisição, permuta ou locação de bem móvel ou imóvel, ou a contratação de serviços pelas entidades referidas no art. 1° por preço superior ao valor de mercado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, III', 'perceber vantagem econômica, direta ou indireta, para facilitar a alienação, permuta ou locação de bem público ou o fornecimento de serviço por ente estatal por preço inferior ao valor de mercado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, IV', 'utilizar, em obra ou serviço particular, qualquer bem móvel, de propriedade ou à disposição de qualquer das entidades referidas no art. 1º desta Lei, bem como o trabalho de servidores, de empregados ou de terceiros contratados por essas entidades;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, V', 'receber vantagem econômica de qualquer natureza, direta ou indireta, para tolerar a exploração ou a prática de jogos de azar, de lenocínio, de narcotráfico, de contrabando, de usura ou de qualquer outra atividade ilícita, ou aceitar promessa de tal vantagem;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, VI', 'receber vantagem econômica de qualquer natureza, direta ou indireta, para fazer declaração falsa sobre qualquer dado técnico que envolva obras públicas ou qualquer outro serviço ou sobre quantidade, peso, medida, qualidade ou característica de mercadorias ou bens fornecidos a qualquer das entidades referidas no art. 1º desta Lei;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, VII', 'adquirir, para si ou para outrem, no exercício de mandato, de cargo, de emprego ou de função pública, e em razão deles, bens de qualquer natureza, decorrentes dos atos descritos no caput deste artigo, cujo valor seja desproporcional à evolução do patrimônio ou à renda do agente público, assegurada a demonstração pelo agente da licitude da origem dessa evolução;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, VIII', 'aceitar emprego, comissão ou exercer atividade de consultoria ou assessoramento para pessoa física ou jurídica que tenha interesse suscetível de ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público, durante a atividade;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, IX', 'perceber vantagem econômica para intermediar a liberação ou aplicação de verba pública de qualquer natureza;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, X', 'receber vantagem econômica de qualquer natureza, direta ou indiretamente, para omitir ato de ofício, providência ou declaração a que esteja obrigado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, XI', 'incorporar, por qualquer forma, ao seu patrimônio bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1° desta lei;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 9º, XII', 'usar, em proveito próprio, bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1° desta lei. Seção II Dos Atos de Improbidade Administrativa que Causam Prejuízo ao Erário', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10 (caput)', 'Constitui ato de improbidade administrativa que causa lesão ao erário qualquer ação ou omissão dolosa, que enseje, efetiva e comprovadamente, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação dos bens ou haveres das entidades referidas no art. 1º desta Lei, e notadamente:', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, I', 'facilitar ou concorrer, por qualquer forma, para a indevida incorporação ao patrimônio particular, de pessoa física ou jurídica, de bens, de rendas, de verbas ou de valores integrantes do acervo patrimonial das entidades referidas no art. 1º desta Lei;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, II', 'permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1º desta lei, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, III', 'doar à pessoa física ou jurídica bem como ao ente despersonalizado, ainda que de fins educativos ou assistências, bens, rendas, verbas ou valores do patrimônio de qualquer das entidades mencionadas no art. 1º desta lei, sem observância das formalidades legais e regulamentares aplicáveis à espécie;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, IV', 'permitir ou facilitar a alienação, permuta ou locação de bem integrante do patrimônio de qualquer das entidades referidas no art. 1º desta lei, ou ainda a prestação de serviço por parte delas, por preço inferior ao de mercado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, V', 'permitir ou facilitar a aquisição, permuta ou locação de bem ou serviço por preço superior ao de mercado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, VI', 'realizar operação financeira sem observância das normas legais e regulamentares ou aceitar garantia insuficiente ou inidônea;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, VII', 'conceder benefício administrativo ou fiscal sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, VIII', 'frustrar a licitude de processo licitatório ou de processo seletivo para celebração de parcerias com entidades sem fins lucrativos, ou dispensá-los indevidamente, acarretando perda patrimonial efetiva;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, IX', 'ordenar ou permitir a realização de despesas não autorizadas em lei ou regulamento;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, X', 'agir ilicitamente na arrecadação de tributo ou de renda, bem como no que diz respeito à conservação do patrimônio público;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XI', 'liberar verba pública sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XII', 'permitir, facilitar ou concorrer para que terceiro se enriqueça ilicitamente;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XIII', 'permitir que se utilize, em obra ou serviço particular, veículos, máquinas, equipamentos ou material de qualquer natureza, de propriedade ou à disposição de qualquer das entidades mencionadas no art. 1° desta lei, bem como o trabalho de servidor público, empregados ou terceiros contratados por essas entidades. XIV – celebrar contrato ou outro instrumento que tenha por objeto a prestação de serviços públicos por meio da gestão associada sem observar as formalidades previstas na lei; XV – celebrar contrato de rateio de consórcio público sem suficiente e prévia dotação orçamentária, ou sem observar as formalidades previstas na lei.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XVI', 'facilitar ou concorrer, por qualquer forma, para a incorporação, ao patrimônio particular de pessoa física ou jurídica, de bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidades privadas mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; (Vigência)', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XVII', 'permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidade privada mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; (Vigência)', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XVIII', 'celebrar parcerias da administração pública com entidades privadas sem a observância das formalidades legais ou regulamentares aplicáveis à espécie; (Vigência)', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XIX', 'agir para a configuração de ilícito na celebração, na fiscalização e na análise das prestações de contas de parcerias firmadas pela administração pública com entidades privadas;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XX', 'liberar recursos de parcerias firmadas pela administração pública com entidades privadas sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XXI', ';', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, XXII', 'conceder, aplicar ou manter benefício financeiro ou tributário contrário ao que dispõem o caput e o § 1º do art. 8º-A da Lei Complementar nº 116, de 31 de julho de 2003.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, § 1º', 'Nos casos em que a inobservância de formalidades legais ou regulamentares não implicar perda patrimonial efetiva, não ocorrerá imposição de ressarcimento, vedado o enriquecimento sem causa das entidades referidas no art. 1º desta Lei.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 10, § 2º', 'A mera perda patrimonial decorrente da atividade econômica não acarretará improbidade administrativa, salvo se comprovado ato doloso praticado com essa finalidade. Dos Atos de Improbidade Administrativa Decorrentes de Concessão ou Aplicação Indevida de Benefício Financeiro ou Tributário Seção III Dos Atos de Improbidade Administrativa que Atentam Contra os Princípios da Administração Pública', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11 (caput)', 'Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a ação ou omissão dolosa que viole os deveres de honestidade, de imparcialidade e de legalidade, caracterizada por uma das seguintes condutas:', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, I', ';', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, II', ';', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, III', 'revelar fato ou circunstância de que tem ciência em razão das atribuições e que deva permanecer em segredo, propiciando beneficiamento por informação privilegiada ou colocando em risco a segurança da sociedade e do Estado;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, IV', 'negar publicidade aos atos oficiais, exceto em razão de sua imprescindibilidade para a segurança da sociedade e do Estado ou de outras hipóteses instituídas em lei;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, V', 'frustrar, em ofensa à imparcialidade, o caráter concorrencial de concurso público, de chamamento ou de procedimento licitatório, com vistas à obtenção de benefício próprio, direto ou indireto, ou de terceiros;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, VI', 'deixar de prestar contas quando esteja obrigado a fazê-lo, desde que disponha das condições para isso, com vistas a ocultar irregularidades;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, VII', 'revelar ou permitir que chegue ao conhecimento de terceiro, antes da respectiva divulgação oficial, teor de medida política ou econômica capaz de afetar o preço de mercadoria, bem ou serviço.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, VIII', 'descumprir as normas relativas à celebração, fiscalização e aprovação de contas de parcerias firmadas pela administração pública com entidades privadas. (Vigência)', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, IX', ';', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, X', ';', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, XI', 'nomear cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, da autoridade nomeante ou de servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento, para o exercício de cargo em comissão ou de confiança ou, ainda, de função gratificada na administração pública direta e indireta em qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, compreendido o ajuste mediante designações recíprocas;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, XII', 'praticar, no âmbito da administração pública e com recursos do erário, ato de publicidade que contrarie o disposto no § 1º do art. 37 da Constituição Federal, de forma a promover inequívoco enaltecimento do agente público e personalização de atos, de programas, de obras, de serviços ou de campanhas dos órgãos públicos.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 1º', 'Nos termos da Convenção das Nações Unidas contra a Corrupção, promulgada pelo Decreto nº 5.687, de 31 de janeiro de 2006, somente haverá improbidade administrativa, na aplicação deste artigo, quando for comprovado na conduta funcional do agente público o fim de obter proveito ou benefício indevido para si ou para outra pessoa ou entidade.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 2º', 'Aplica-se o disposto no § 1º deste artigo a quaisquer atos de improbidade administrativa tipificados nesta Lei e em leis especiais e a quaisquer outros tipos especiais de improbidade administrativa instituídos por lei.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 3º', 'O enquadramento de conduta funcional na categoria de que trata este artigo pressupõe a demonstração objetiva da prática de ilegalidade no exercício da função pública, com a indicação das normas constitucionais, legais ou infralegais violadas.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 4º', 'Os atos de improbidade de que trata este artigo exigem lesividade relevante ao bem jurídico tutelado para serem passíveis de sancionamento e independem do reconhecimento da produção de danos ao erário e de enriquecimento ilícito dos agentes públicos.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 5º', 'Não se configurará improbidade a mera nomeação ou indicação política por parte dos detentores de mandatos eletivos, sendo necessária a aferição de dolo com finalidade ilícita por parte do agente. CAPÍTULO III Das Penas', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 11, § 5º, inciso IV', 'na hipótese prevista no art. 10-A, perda da função pública, suspensão dos direitos políticos de 5 (cinco) a 8 (oito) anos e multa civil de até 3 (três) vezes o valor do benefício financeiro ou tributário concedido.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12 (caput)', 'Independentemente do ressarcimento integral do dano patrimonial, se efetivo, e das sanções penais comuns e de responsabilidade, civis e administrativas previstas na legislação específica, está o responsável pelo ato de improbidade sujeito às seguintes cominações, que podem ser aplicadas isolada ou cumulativamente, de acordo com a gravidade do fato:', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, I', 'na hipótese do art. 9º desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, perda da função pública, suspensão dos direitos políticos até 14 (catorze) anos, pagamento de multa civil equivalente ao valor do acréscimo patrimonial e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 14 (catorze) anos;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, II', 'na hipótese do art. 10 desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, se concorrer esta circunstância, perda da função pública, suspensão dos direitos políticos até 12 (doze) anos, pagamento de multa civil equivalente ao valor do dano e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 12 (doze) anos;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, III', 'na hipótese do art. 11 desta Lei, pagamento de multa civil de até 24 (vinte e quatro) vezes o valor da remuneração percebida pelo agente e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 4 (quatro) anos;', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, IV', '.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, parágrafo único', '.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 1º', 'A sanção de perda da função pública, nas hipóteses dos incisos I e II do caput deste artigo, atinge apenas o vínculo de mesma qualidade e natureza que o agente público ou político detinha com o poder público na época do cometimento da infração, podendo o magistrado, na hipótese do inciso I do caput deste artigo, e em caráter excepcional, estendê-la aos demais vínculos, consideradas as circunstâncias do caso e a gravidade da infração.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 2º', 'A multa pode ser aumentada até o dobro, se o juiz considerar que, em virtude da situação econômica do réu, o valor calculado na forma dos incisos I, II e III do caput deste artigo é ineficaz para reprovação e prevenção do ato de improbidade.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 3º', 'Na responsabilização da pessoa jurídica, deverão ser considerados os efeitos econômicos e sociais das sanções, de modo a viabilizar a manutenção de suas atividades.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 4º', 'Em caráter excepcional e por motivos relevantes devidamente justificados, a sanção de proibição de contratação com o poder público pode extrapolar o ente público lesado pelo ato de improbidade, observados os impactos econômicos e sociais das sanções, de forma a preservar a função social da pessoa jurídica, conforme disposto no § 3º deste artigo.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 5º', 'No caso de atos de menor ofensa aos bens jurídicos tutelados por esta Lei, a sanção limitar-se-á à aplicação de multa, sem prejuízo do ressarcimento do dano e da perda dos valores obtidos, quando for o caso, nos termos do caput deste artigo.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 6º', 'Se ocorrer lesão ao patrimônio público, a reparação do dano a que se refere esta Lei deverá deduzir o ressarcimento ocorrido nas instâncias criminal, civil e administrativa que tiver por objeto os mesmos fatos.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 7º', 'As sanções aplicadas a pessoas jurídicas com base nesta Lei e na Lei nº 12.846, de 1º de agosto de 2013, deverão observar o princípio constitucional do non bis in idem.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 8º', 'A sanção de proibição de contratação com o poder público deverá constar do Cadastro Nacional de Empresas Inidôneas e Suspensas (CEIS) de que trata a Lei nº 12.846, de 1º de agosto de 2013, observadas as limitações territoriais contidas em decisão judicial, conforme disposto no § 4º deste artigo.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 9º', 'As sanções previstas neste artigo somente poderão ser executadas após o trânsito em julgado da sentença condenatória.', '1992-06-02', 14, 66),
('Lei nº 8.429/1992 — art. 12, § 10', 'Para efeitos de contagem do prazo da sanção de suspensão dos direitos políticos, computar-se-á retroativamente o intervalo de tempo entre a decisão colegiada e o trânsito em julgado da sentença condenatória. CAPÍTULO IV Da Declaração de Bens', '1992-06-02', 14, 66),
('Lei nº 14.133/2021 — art. 17 (caput)', 'O processo de licitação observará as seguintes fases, em sequência:', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, I', 'preparatória;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, II', 'de divulgação do edital de licitação; III - de apresentação de propostas e lances, quando for o caso;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, IV', 'de julgamento;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, V', 'de habilitação;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, VI', 'recursal; VII - de homologação.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 1º', 'A fase referida no inciso V do caput deste artigo poderá, mediante ato motivado com explicitação dos benefícios decorrentes, anteceder as fases referidas nos incisos III e IV do caput deste artigo, desde que expressamente previsto no edital de licitação.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 2º', 'As licitações serão realizadas preferencialmente sob a forma eletrônica, admitida a utilização da forma presencial, desde que motivada, devendo a sessão pública ser registrada em ata e gravada em áudio e vídeo.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 3º', 'Desde que previsto no edital, na fase a que se refere o inciso IV do caput deste artigo, o órgão ou entidade licitante poderá, em relação ao licitante provisoriamente vencedor, realizar análise e avaliação da conformidade da proposta, mediante homologação de amostras, exame de conformidade e prova de conceito, entre outros testes de interesse da Administração, de modo a comprovar sua aderência às especificações definidas no termo de referência ou no projeto básico.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 4º', 'Nos procedimentos realizados por meio eletrônico, a Administração poderá determinar, como condição de validade e eficácia, que os licitantes pratiquem seus atos em formato eletrônico.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 5º', 'Na hipótese excepcional de licitação sob a forma presencial a que refere o § 2º deste artigo, a sessão pública de apresentação de propostas deverá ser gravada em áudio e vídeo, e a gravação será juntada aos autos do processo licitatório depois de seu encerramento.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 6º', 'A Administração poderá exigir certificação por organização independente acreditada pelo Instituto Nacional de Metrologia, Qualidade e Tecnologia (Inmetro) como condição para aceitação de:', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 6º, inciso I', 'estudos, anteprojetos, projetos básicos e projetos executivos;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 17, § 6º, inciso II', 'conclusão de fases ou de objetos de contratos; III - material e corpo técnico apresentados por empresa para fins de habilitação. CAPÍTULO II DA FASE PREPARATÓRIA Seção I Da Instrução do Processo Licitatório', '2021-04-01', 14, 95)
